a<-commandArgs(TRUE);if(length(a)<3)stop("Usage: train_survivalsvm.R <dev> <val> <out> [vars] [seed]");if(!requireNamespace("survivalsvm",quietly=TRUE)||!requireNamespace("survival",quietly=TRUE))stop("Install survivalsvm and survival");tr<-read.csv(a[1],check.names=FALSE);va<-read.csv(a[2],check.names=FALSE);out<-a[3];v<-if(length(a)>=4)strsplit(a[4],",",TRUE)[[1]]else setdiff(names(tr),c("Time","Event"));seed<-if(length(a)>=5)as.integer(a[5])else 123L;dir.create(out,recursive=TRUE,showWarnings=FALSE);set.seed(seed);f<-as.formula(paste("survival::Surv(Time,Event)~",paste(v,collapse="+")));fit<-survivalsvm::survivalsvm(f,tr,gamma.mu=.5,opt.meth="quadprog",diff.meth="makediff3",kernel="lin_kernel",sgf.sv=5,sigf=7,maxiter=100,margin=.1,bound=10);score<-function(d)as.numeric(predict(fit,d)$predicted);write.csv(data.frame(Time=tr$Time,Event=tr$Event,Survivalsvm=score(tr)),file.path(out,"development_survivalsvm_predictions.csv"),row.names=FALSE);write.csv(data.frame(Time=va$Time,Event=va$Event,Survivalsvm=score(va)),file.path(out,"validation_survivalsvm_predictions.csv"),row.names=FALSE);saveRDS(list(model=fit,predictors=v),file.path(out,"survivalsvm_model.rds"))
